const formatTurnTimestamp = (isoTimestamp) => {
    const date = new Date(isoTimestamp);
    if (Number.isNaN(date.getTime()))
        return '';
    const day = date.getDate();
    const month = date.toLocaleString('en-US', { month: 'short' });
    const time = date.toLocaleString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
    return `${day} ${month} · ${time}`;
};
const getSourceUrl = (domain) => {
    const trimmedDomain = domain.trim();
    if (trimmedDomain.startsWith('http://') || trimmedDomain.startsWith('https://')) {
        return trimmedDomain;
    }
    return `https://${trimmedDomain}`;
};
const formatRecentDate = (date) => date.toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
});
const formatRecentMonth = (date) => date.toLocaleDateString('en-GB', {
    month: 'short',
    year: 'numeric',
});
const getRecentChatDateLabel = (openedAt) => {
    const openedDate = new Date(openedAt);
    const nowDate = new Date();
    const openedDay = new Date(openedDate.getFullYear(), openedDate.getMonth(), openedDate.getDate());
    const today = new Date(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate());
    const diffInDays = Math.floor((today.getTime() - openedDay.getTime()) / (1000 * 60 * 60 * 24));
    if (diffInDays === 0)
        return 'Today';
    if (diffInDays >= 1 && diffInDays <= 6)
        return formatRecentDate(openedDay);
    if (diffInDays >= 7 && diffInDays <= 13)
        return 'One week ago';
    return formatRecentMonth(openedDay);
};
