const resolveStrategyChannel = (mediaType) => {
    const value = mediaType.toLowerCase();
    if (value.includes('metasearch'))
        return 'METASEARCH';
    if (value.includes('youtube') || value.includes('video'))
        return 'VIDEO';
    if (value.includes('social') || value.includes('tiktok') || value.includes('facebook'))
        return 'SOCIAL';
    if (value.includes('display') || value.includes('dsp') || value.includes('demand gen'))
        return 'DISPLAY';
    if (value.includes('ppc') || value.includes('search') || value.includes('performance max'))
        return 'PAID_SEARCH';
    return 'OTHER';
};
